    ink = max(ink, line(m.z - hinge) * within(ax, 1.5, 4.2) * wingish);
    ink = max(ink, line(m.z - slat) * within(ax, 1.55, 4.2) * wingish * past(m.z + 0.9));
    ink = max(ink, line(ax - 4.2) * within(m.z, -3.9, -0.5) * wingish * past(-0.3 - m.y));
